import { memo } from 'react';

import { TemplateSlide } from 'components';
import { useBffData } from 'hooks';
import { TopBottomBarChartSlideContent } from 'pages/components/ValueCreation/Slides/TopBottomBarChartSlideContent';
import { TopBottomWaterfallSlideContent } from 'pages/components/ValueCreation/Slides/TopBottomWaterfallSlideContent';
import { KPI_CONFIGS } from 'pages/pillars/ValueCreation/VolumePages/config';
import { useVolumePagesKpi } from 'pages/pillars/ValueCreation/VolumePages/contexts';
import {
  barChartWithLegend,
  volumePagePrefixedTestId,
  waterfallChartWithLegend,
} from 'pages/pillars/ValueCreation/VolumePages/utils';
import { PageInfo } from 'pages/types';
import { StyledExportPageSection } from 'shared/Styles/exportPages.styles';
import { isMarketShareKpi } from 'utils';

interface TopBrandsSlideProps {
  periodLabel: 'YTD' | 'MTD';
  pageSectionName: string;
  getPageByName: (name: string) => PageInfo | undefined;
  dataTestId?: string;
  globalData: ReturnType<typeof useBffData>;
  period: string;
}

export const TopBrandsSlide = memo(
  ({
    periodLabel,
    pageSectionName,
    getPageByName,
    dataTestId,
    globalData,
    period,
  }: TopBrandsSlideProps) => {
    const { kpi, kpiName } = useVolumePagesKpi();
    const waterfallLegend = KPI_CONFIGS[kpi].legend.default;
    const isMarketShare = isMarketShareKpi(kpi);

    const dataTopKey = `brand-top-${periodLabel}` as const;
    const dataBottomKey = `brand-bottom-${periodLabel}` as const;
    const chartHeightMarketShare = '190px';
    const chartHeightDefault = '144px';

    const footnotes = isMarketShare
      ? 'Brands are ordered by: Mrkt. Share delta weighted by country NR contribution.'
      : 'Brands are ordered by: Global Brands shown first as consolidated, then ranked by OG vs LY';

    return (
      <StyledExportPageSection data-page-name={pageSectionName}>
        <TemplateSlide
          enablePngCopy
          title={`${periodLabel} Top and Bottom 15 Brands by ${kpiName}`}
          measure={KPI_CONFIGS[kpi].measure}
          period={period}
          footnotes={footnotes}
          page={getPageByName(pageSectionName)?.index}
          countryId="ABI"
          headerDivider={false}
          dataTestId={volumePagePrefixedTestId(dataTestId, pageSectionName)}
        >
          {isMarketShare ? (
            <TopBottomBarChartSlideContent
              dataTestId={volumePagePrefixedTestId(
                dataTestId,
                `summary-top-brands-${periodLabel.toLowerCase()}`,
              )}
              loading={globalData.loading}
              error={globalData.error}
              data={{
                topKpiData: barChartWithLegend(
                  globalData.data,
                  dataTopKey,
                  waterfallLegend,
                ),
                bottomKpiData: barChartWithLegend(
                  globalData.data,
                  dataBottomKey,
                  waterfallLegend,
                ),
              }}
              chartHeight={chartHeightMarketShare}
            />
          ) : (
            <TopBottomWaterfallSlideContent
              dataTestId={volumePagePrefixedTestId(
                dataTestId,
                `summary-top-brands-${periodLabel.toLowerCase()}`,
              )}
              data={{
                topKpiData: waterfallChartWithLegend(
                  globalData.data,
                  dataTopKey,
                  waterfallLegend,
                ),
                bottomKpiData: waterfallChartWithLegend(
                  globalData.data,
                  dataBottomKey,
                  waterfallLegend,
                ),
              }}
              loading={globalData.loading}
              error={globalData.error}
              chartHeight={chartHeightDefault}
            />
          )}
        </TemplateSlide>
      </StyledExportPageSection>
    );
  },
);

TopBrandsSlide.displayName = 'TopBrandsSlide';
